import os
import sys
import json
import re
from datetime import datetime

def parse_date(date_str):
    if not date_str: 
        return None
    date_str = date_str.strip()
    # Remove ordinal suffixes
    date_str = re.sub(r'(?<=\d)(st|nd|rd|th)', '', date_str)
    formats = ['%B %d, %Y', '%b %d, %Y', '%d %B %Y', '%d %b %Y']
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return None

def extract_values(text, patterns, is_date=False):
    for pattern in patterns:
        m = re.search(pattern, text)
        if m:
            val = m.group(1)
            if is_date:
                return parse_date(val)
            else:
                return val.replace(',', '')
    return None

def process_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    messages = content.split('========================================================================')
    parsed_messages = []
    for msg in messages:
        msg = msg.strip()
        if not msg: 
            continue
        po_match = re.search(r'PO-\d{5}', msg)
        if po_match:
            po = po_match.group(0)
            parsed_messages.append((po, msg))
    return parsed_messages

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    directory = sys.argv[1]

    extraction_rules = {
        'invoices.txt': {
            'invoice amount': (
                [
                    r'comes to \$([\d,\.]+) in total',
                    r'comes to ([\d,\.]+) dollars in total',
                    r'Invoice total is \$([\d,\.]+) all told',
                    r'Invoice total is ([\d,\.]+) dollars all told'
                ],
                False
            ),
            'quantity invoiced': (
                [
                    r'charged us for ([\d,\.]+) units',
                    r'charged us for ([\d,\.]+) pieces',
                    r'lists ([\d,\.]+) units as the chargeable count',
                    r'lists ([\d,\.]+) pieces as the chargeable count'
                ],
                False
            ),
            'payment due': (
                [
                    r'settled no later than ([A-Za-z0-9\s,]+)\.',
                    r'Payment has to go out by ([A-Za-z0-9\s,]+)\.'
                ],
                True
            )
        },
        'purchase_orders.txt': {
            'order amount': (
                [
                    r'Committed value on the PO is \$([\d,\.]+) overall',
                    r'Committed value on the PO is ([\d,\.]+) dollars overall',
                    r'PO was raised for \$([\d,\.]+) in total',
                    r'PO was raised for ([\d,\.]+) dollars in total'
                ],
                False
            )
        },
        'receipts.txt': {
            'quantity received': (
                [
                    r'counted ([\d,\.]+) pieces on arrival',
                    r'counted ([\d,\.]+) units on arrival',
                    r'tallied ([\d,\.]+) pieces off the truck',
                    r'tallied ([\d,\.]+) units off the truck'
                ],
                False
            ),
            'goods received': (
                [
                    r'logged as received on ([A-Za-z0-9\s,]+)\.',
                    r'booked in on ([A-Za-z0-9\s,]+)\.'
                ],
                True
            )
        },
        'warehouse_scans.txt': {
            'goods received': (
                [
                    r'picked it up on ([A-Za-z0-9\s,]+)\.',
                    r'reads ([A-Za-z0-9\s,]+)\.'
                ],
                True
            )
        },
        'payments.txt': {
            'payment date': (
                [
                    r'released to the vendor on ([A-Za-z0-9\s,]+)\.',
                    r'sent the money on ([A-Za-z0-9\s,]+)\.'
                ],
                True
            )
        }
    }

    doc_data = {doc: {} for doc in extraction_rules}
    entities = set()

    # Scan all txt files to find all entities
    for filename in os.listdir(directory):
        if filename.endswith('.txt'):
            filepath = os.path.join(directory, filename)
            with open(filepath, 'r', encoding='utf-8') as f:
                entities.update(re.findall(r'PO-\d{5}', f.read()))

    entities = sorted(list(entities))

    # Extract facts from documents
    for doc_name, rules in extraction_rules.items():
        filepath = os.path.join(directory, doc_name)
        if not os.path.exists(filepath):
            continue
        messages = process_file(filepath)
        for po, msg in messages:
            if po not in doc_data[doc_name]:
                doc_data[doc_name][po] = {fact: set() for fact in rules}

            for fact, (patterns, is_date) in rules.items():
                val = extract_values(msg, patterns, is_date)
                if val is not None:
                    doc_data[doc_name][po][fact].add(val)

    rules_info = {
        'pa.three_way_match': {
            'invoice amount': ['invoices.txt'],
            'order amount': ['purchase_orders.txt'],
            'quantity received': ['receipts.txt'],
            'quantity invoiced': ['invoices.txt']
        },
        'pa.paid_in_window': {
            'goods received': ['receipts.txt', 'warehouse_scans.txt'],
            'payment date': ['payments.txt'],
            'payment due': ['invoices.txt']
        }
    }

    output = {}
    for rule, facts in rules_info.items():
        for entity in entities:
            pair_id = f"{rule}::{entity}"
            output[pair_id] = {}
            for fact, docs in facts.items():
