                for doc in docs:
                    if entity in doc_data.get(doc, {}) and fact in doc_data[doc][entity]:
                        vals = doc_data[doc][entity][fact]
                        if len(vals) == 1:
                            fact_val = [list(vals)[0], doc]
                            break
                        elif len(vals) > 1:
                            fact_val = "CONFLICT"
                            break
                output[pair_id][fact] = fact_val

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
