import sys
import os
import json
from datetime import datetime

def parse_tsv(filepath):
    data = {}
    if not os.path.exists(filepath):
        return data

    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Skip comments and empty lines
    lines = [line.rstrip('\r\n') for line in lines if not line.startswith('#') and line.strip()]
    if not lines:
        return data

    # Find the order.key row to map columns to entities
    order_keys = []
    for line in lines[1:]:
        parts = line.split('\t')
        if parts[0] == 'order.key':
            order_keys = parts[1:]
            break

    if not order_keys:
        return data

    for entity in order_keys:
        if entity not in data:
            data[entity] = {}

    # Parse attributes for each entity
    for line in lines[1:]:
        parts = line.split('\t')
        attr = parts[0]
        if attr == 'order.key':
            continue
        values = parts[1:]
        for i, val in enumerate(values):
            if i < len(order_keys):
                entity = order_keys[i]
                if val != '~':
                    if attr not in data[entity]:
                        data[entity][attr] = []
                    data[entity][attr].append(val)

    return data

def format_value(val, attr):
    # Convert ISO week dates to YYYY-MM-DD
    if attr.endswith('.wk'):
        dt = datetime.strptime(val, "%G-W%V-%u")
        return dt.strftime("%Y-%m-%d")
    return val

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    files = [
        "invoices.tsv",
        "payments.tsv",
        "purchase_orders.tsv",
        "receipts.tsv",
        "requisitions.tsv",
        "warehouse_scans.tsv"
    ]

    db = {}
    entities = set()
    for filename in files:
        filepath = os.path.join(dir_path, filename)
        file_data = parse_tsv(filepath)
        db[filename] = file_data
        entities.update(file_data.keys())

    entities = sorted(list(entities))

    # Define the decision rules and their data sources (with fallbacks)
    RULES = {
        "pa.three_way_match": {
            "invoice amount": [("invoices.tsv", "bill.value.usd")],
            "order amount": [("purchase_orders.tsv", "order.commit.usd")],
            "quantity received": [("receipts.tsv", "goodsin.units")],
            "quantity invoiced": [("invoices.tsv", "bill.qty.units")]
        },
        "pa.paid_in_window": {
            "goods received": [("receipts.tsv", "goodsin.day.wk"), ("warehouse_scans.tsv", "scanner.hit.wk")],
            "payment date": [("payments.tsv", "funds.out.wk")],
            "payment due": [("invoices.tsv", "bill.deadline.wk")]
        }
    }

    output = {}

    for rule_name, facts in RULES.items():
        for entity in entities:
            pair_id = f"{rule_name}::{entity}"
            pair_result = {}

            for fact_name, sources in facts.items():
                fact_value = "ABSENT"
                for filename, attr in sources:
                    if filename not in db:
                        continue
                    file_data = db[filename]
                    if entity not in file_data:
                        continue
                    entity_data = file_data[entity]
                    if attr not in entity_data:
                        continue

                    values = entity_data[attr]
                    unique_values = set(values)

                    if len(unique_values) == 1:
                        val = unique_values.pop()
                        formatted_val = format_value(val, attr)
                        fact_value = [formatted_val, filename]
                        break
                    elif len(unique_values) > 1:
                        fact_value = "CONFLICT"
                        break

                pair_result[fact_name] = fact_value

            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
