import sys
import os
import json
import datetime

def convert_date(wk_str):
    if wk_str == "~":
        return "~"
    # Parse ISO 8601 week date (YYYY-Www-D)
    dt = datetime.datetime.strptime(wk_str, "%G-W%V-%u")
    return dt.strftime("%Y-%m-%d")

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    files = [
        "invoices.tsv",
        "payments.tsv",
        "purchase_orders.tsv",
        "receipts.tsv",
        "requisitions.tsv",
        "warehouse_scans.tsv"
    ]

    data = {}
    all_order_keys = set()

    # Read and parse all TSV files
    for filename in files:
        doc_name = filename.replace('.tsv', '')
        data[doc_name] = {}
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            continue

        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        # Skip comments and empty lines
        lines = [line.strip('\n') for line in lines if not line.startswith('#') and line.strip('\n').strip()]
        if not lines:
            continue

        order_keys = []
        for line in lines:
            parts = line.split('\t')
            if parts[0] == 'order.key':
                order_keys = parts[1:]
                break

        for okey in order_keys:
            if okey != '~':
                all_order_keys.add(okey)

        for line in lines:
            parts = line.split('\t')
            attr = parts[0]
            if attr == 'order.key':
                continue
            values = parts[1:]
            for i, val in enumerate(values):
                if i < len(order_keys):
                    okey = order_keys[i]
                    if okey == '~':
                        continue
                    if okey not in data[doc_name]:
                        data[doc_name][okey] = {}
                    if attr not in data[doc_name][okey]:
                        data[doc_name][okey][attr] = set()
                    if val != '~':
                        if attr.endswith('.wk'):
                            val = convert_date(val)
                        data[doc_name][okey][attr].add(val)

    # Define decision rules and their data sources (primary, then fallback)
    RULES = {
        "pa.three_way_match": {
            "invoice amount": [("invoices", "bill.value.usd")],
            "order amount": [("purchase_orders", "order.commit.usd")],
            "quantity received": [("receipts", "goodsin.units")],
            "quantity invoiced": [("invoices", "bill.qty.units")]
        },
        "pa.paid_in_window": {
            "goods received": [("receipts", "goodsin.day.wk"), ("warehouse_scans", "scanner.hit.wk")],
            "payment date": [("payments", "funds.out.wk")],
            "payment due": [("invoices", "bill.deadline.wk")]
        }
    }

    output = {}

    # Evaluate facts for each rule and each order key
    for rule_name, facts in RULES.items():
        for okey in sorted(all_order_keys):
            pair_id = f"{rule_name}::{okey}"
            output[pair_id] = {}

            for fact_name, sources in facts.items():
                fact_result = "ABSENT"

                for doc_name, attr in sources:
                    doc_data = data.get(doc_name, {})
                    okey_data = doc_data.get(okey, {})
                    values = okey_data.get(attr, set())

                    if len(values) > 1:
                        fact_result = "CONFLICT"
                        break
                    elif len(values) == 1:
                        val = list(values)[0]
                        fact_result = [val, doc_name]
                        break
                    # If len(values) == 0, it continues to the fallback document (if any)

                output[pair_id][fact_name] = fact_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
