import sys
import os
import json

def parse_date(d):
    if not d: return None
    m, day, y = d.split('/')
    return f"{y}-{m}-{day}"

def load_data(dir_path):
    data = {}
    all_pos = set()
    files = [
        "invoices.txt", 
        "payments.txt", 
        "purchase_orders.txt", 
        "receipts.txt", 
        "warehouse_scans.txt", 
        "requisitions.txt"
    ]
    for f in files:
        path = os.path.join(dir_path, f)
        data[f] = {}
        if not os.path.exists(path):
            continue
        with open(path, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split('|')
                if len(parts) > 1:
                    po = parts[1]
                    all_pos.add(po)
                    if po not in data[f]:
                        data[f][po] = []
                    data[f][po].append(parts)
    return data, sorted(list(all_pos))

facts_info = {
    "pa.three_way_match": {
        "invoice amount": [("invoices", "invoices.txt", 4, "amount")],
        "order amount": [("purchase_orders", "purchase_orders.txt", 4, "amount")],
        "quantity received": [("receipts", "receipts.txt", 4, "amount")],
        "quantity invoiced": [("invoices", "invoices.txt", 6, "amount")]
    },
    "pa.paid_in_window": {
        "goods received": [("receipts", "receipts.txt", 6, "date"), ("warehouse_scans", "warehouse_scans.txt", 4, "date")],
        "payment date": [("payments", "payments.txt", 4, "date")],
        "payment due": [("invoices", "invoices.txt", 7, "date")]
    }
}

def extract_fact(po, sources, data):
    for doc_name, file_name, col_idx, val_type in sources:
        if file_name not in data or po not in data[file_name]:
            continue

        rows = data[file_name][po]
        values = set()
        for row in rows:
            if col_idx < len(row):
                val = row[col_idx].strip()
                if val:
                    if val_type == "date":
                        val = parse_date(val)
                    values.add(val)

        if len(values) == 1:
            return [list(values)[0], doc_name]
        elif len(values) > 1:
            return "CONFLICT"

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]
    data, all_pos = load_data(dir_path)

    results = {}
    for rule, facts in facts_info.items():
        for po in all_pos:
            pair_id = f"{rule}::{po}"
            results[pair_id] = {}
            for fact_name, sources in facts.items():
                results[pair_id][fact_name] = extract_fact(po, sources, data)

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
