import sys
import os
import json

def parse_date(val):
    m, d, y = val.split('/')
    return f"{y}-{m}-{d}"

def main():
    dir_path = sys.argv[1]

    invoice_amount = {}
    quantity_invoiced = {}
    payment_due = {}
    order_amount = {}
    quantity_received = {}
    goods_received_receipts = {}
    payment_date = {}
    goods_received_warehouse = {}

    all_entities = set()

    # Collect all entities from all txt files
    for filename in os.listdir(dir_path):
        if filename.endswith('.txt'):
            filepath = os.path.join(dir_path, filename)
            with open(filepath, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#') or line.startswith('TRANSACTION_ID|'):
                        continue
                    parts = line.split('|')
                    if len(parts) > 1:
                        entity = parts[1].strip()
                        if entity:
                            all_entities.add(entity)

    def read_file(filename, extractors):
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            return
        with open(filepath, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#') or line.startswith('TRANSACTION_ID|'):
                    continue
                parts = line.split('|')
                if len(parts) > 1:
                    entity = parts[1].strip()
                    if not entity:
                        continue
                    for col_idx, is_date, data_dict in extractors:
                        if len(parts) > col_idx:
                            val = parts[col_idx].strip()
                            if val:
                                if is_date:
                                    val = parse_date(val)
                                if entity not in data_dict:
                                    data_dict[entity] = set()
                                data_dict[entity].add(val)

    read_file('invoices.txt', [
        (4, False, invoice_amount),
        (6, False, quantity_invoiced),
        (7, True, payment_due)
    ])

    read_file('purchase_orders.txt', [
        (4, False, order_amount)
    ])

    read_file('receipts.txt', [
        (4, False, quantity_received),
        (6, True, goods_received_receipts)
    ])

    read_file('payments.txt', [
        (4, True, payment_date)
    ])

    read_file('warehouse_scans.txt', [
        (4, True, goods_received_warehouse)
    ])

    def get_fact(entity, primary_data, primary_doc, fallback_data=None, fallback_doc=None):
        if entity in primary_data and primary_data[entity]:
            vals = primary_data[entity]
            if len(vals) > 1:
                return "CONFLICT"
            else:
                return [list(vals)[0], primary_doc]
        elif fallback_data is not None:
            if entity in fallback_data and fallback_data[entity]:
                vals = fallback_data[entity]
                if len(vals) > 1:
                    return "CONFLICT"
                else:
                    return [list(vals)[0], fallback_doc]
        return "ABSENT"

    result = {}

    for entity in sorted(list(all_entities)):
        # pa.three_way_match
        pair_id_1 = f"pa.three_way_match::{entity}"
        result[pair_id_1] = {
            "invoice amount": get_fact(entity, invoice_amount, "invoices"),
            "order amount": get_fact(entity, order_amount, "purchase_orders"),
            "quantity received": get_fact(entity, quantity_received, "receipts"),
            "quantity invoiced": get_fact(entity, quantity_invoiced, "invoices")
        }

        # pa.paid_in_window
        pair_id_2 = f"pa.paid_in_window::{entity}"
        result[pair_id_2] = {
            "goods received": get_fact(entity, goods_received_receipts, "receipts", goods_received_warehouse, "warehouse_scans"),
            "payment date": get_fact(entity, payment_date, "payments"),
            "payment due": get_fact(entity, payment_due, "invoices")
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
