import os
import sys
import re
import json
from collections import defaultdict

def extract_data(directory):
    months = {
        "Jan.": "01", "Feb.": "02", "March": "03", "April": "04",
        "May": "05", "June": "06", "July": "07", "Aug.": "08",
        "Sept.": "09", "Oct.": "10", "Nov.": "11", "Dec.": "12"
    }

    def parse_date(val):
        m = re.search(r"(Jan\.|Feb\.|March|April|May|June|July|Aug\.|Sept\.|Oct\.|Nov\.|Dec\.)\s+(\d{1,2}),\s+(\d{4})", val)
        if m:
            return f"{m.group(3)}-{months[m.group(1)]}-{m.group(2).zfill(2)}"
        return None

    def parse_amount(val):
        m = re.search(r"USD\s+([\d,]+\.\d{2})", val)
        if m:
            return m.group(1).replace(",", "")
        return None

    def parse_quantity(val):
        m = re.search(r"([\d,]+)\s+pcs", val)
        if m:
            return m.group(1).replace(",", "")
        return None

    # data[po][fact][doc] = set_of_values
    data = defaultdict(lambda: defaultdict(lambda: defaultdict(set)))

    files_info = {
        "invoices.html": {
            "doc_name": "invoices",
            "fields": {
                "Invoice grand total": ("invoice amount", parse_amount),
                "Units charged": ("quantity invoiced", parse_quantity),
                "Payment deadline": ("payment due", parse_date)
            }
        },
        "payments.html": {
            "doc_name": "payments",
            "fields": {
                "Funds released": ("payment date", parse_date)
            }
        },
        "purchase_orders.html": {
            "doc_name": "purchase_orders",
            "fields": {
                "Total order value": ("order amount", parse_amount)
            }
        },
        "receipts.html": {
            "doc_name": "receipts",
            "fields": {
                "Units counted on delivery": ("quantity received", parse_quantity),
                "Delivery booked": ("goods received", parse_date)
            }
        },
        "warehouse_scans.html": {
            "doc_name": "warehouse_scans",
            "fields": {
                "Dock scanner stamp": ("goods received", parse_date)
            }
        }
    }

    for filename, info in files_info.items():
        filepath = os.path.join(directory, filename)
        if not os.path.exists(filepath):
            continue
        with open(filepath, "r", encoding="utf-8") as f:
            content = f.read()

        articles = re.findall(r'<article class="sheet"[^>]*>(.*?)</article>', content, re.DOTALL)
        for article in articles:
            po_match = re.search(r'<th>Procurement reference</th>\s*<td[^>]*>.*?([A-Z]+-\d+).*?</td>', article)
            if not po_match:
                continue
            po = po_match.group(1)

            fields = re.findall(r'<th>(.*?)</th>\s*<td([^>]*)>(.*?)</td>', article, re.DOTALL)
            for th, td_attrs, td_content in fields:
                th = th.strip()
                if 'class="void"' in td_attrs:
                    continue
                if th in info["fields"]:
                    fact_name, parser = info["fields"][th]
                    val = parser(td_content)
                    if val is not None:
                        data[po][fact_name][info["doc_name"]].add(val)

    pairs = [
        "pa.three_way_match::PO-40301",
        "pa.three_way_match::PO-40302",
        "pa.three_way_match::PO-40303",
        "pa.three_way_match::PO-40304",
        "pa.three_way_match::PO-40305",
        "pa.three_way_match::PO-40306",
        "pa.three_way_match::PO-40307",
        "pa.three_way_match::PO-40308",
        "pa.three_way_match::PO-40309",
