import sys
import os
import re
import json

def strip_tags(text):
    return re.sub(r'<[^>]+>', '', text).strip()

MONTHS = {
    'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04', 'may': '05', 'jun': '06',
    'jul': '07', 'aug': '08', 'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12'
}

def parse_date(d_str):
    m = re.search(r'([A-Z][a-z]+)\.?\s+(\d+),\s+(\d{4})', d_str)
    if m:
        month_str = m.group(1).lower()[:3]
        month = MONTHS[month_str]
        day = f"{int(m.group(2)):02d}"
        year = m.group(3)
        return f"{year}-{month}-{day}"
    return d_str

def parse_amount(a_str):
    m = re.search(r'([\d,\.]+)', a_str)
    if m:
        val = m.group(1).replace(',', '')
        return val
    return a_str

FACT_SOURCES = {
    'invoice amount': {
        'primary': ('invoices', 'Invoice grand total', parse_amount)
    },
    'order amount': {
        'primary': ('purchase_orders', 'Total order value', parse_amount)
    },
    'quantity received': {
        'primary': ('receipts', 'Units counted on delivery', parse_amount)
    },
    'quantity invoiced': {
        'primary': ('invoices', 'Units charged', parse_amount)
    },
    'goods received': {
        'primary': ('receipts', 'Delivery booked', parse_date),
        'fallback': ('warehouse_scans', 'Dock scanner stamp', parse_date)
    },
    'payment date': {
        'primary': ('payments', 'Funds released', parse_date)
    },
    'payment due': {
        'primary': ('invoices', 'Payment deadline', parse_date)
    }
}

RULES = {
    'pa.three_way_match': ['invoice amount', 'order amount', 'quantity received', 'quantity invoiced'],
    'pa.paid_in_window': ['goods received', 'payment date', 'payment due']
}

def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]

    data = {
        'invoices': {},
        'payments': {},
        'purchase_orders': {},
        'receipts': {},
        'requisitions': {},
        'warehouse_scans': {}
    }

    for doc in data.keys():
        filepath = os.path.join(directory, f"{doc}.html")
        if not os.path.exists(filepath):
            continue

        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        sheets = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)
        for sheet in sheets:
            rows = re.findall(r'<tr>\s*<th>(.*?)</th>\s*(<td.*?>.*?</td>)\s*</tr>', sheet, re.DOTALL)
            po = None
            sheet_data = {}
            for th, td in rows:
                th = strip_tags(th)
                if 'class="void"' in td:
                    val = None
                else:
                    val = strip_tags(td)

                if th == 'Procurement reference':
                    po = val
                else:
                    sheet_data[th] = val

            if po:
                if po not in data[doc]:
                    data[doc][po] = {}
                for k, v in sheet_data.items():
                    if v is not None:
                        if k not in data[doc][po]:
                            data[doc][po][k] = set()
                        data[doc][po][k].add(v)

    all_pos = set()
    for doc_data in data.values():
        all_pos.update(doc_data.keys())

    all_pos = sorted(list(all_pos))

    output = {}

    for rule, facts in RULES.items():
        for po in all_pos:
            pair_id = f"{rule}::{po}"
            output[pair_id] = {}

            for fact in facts:
                source = FACT_SOURCES[fact]

                # Try primary document
                doc, field, parser = source['primary']
                vals = data.get(doc, {}).get(po, {}).get(field, set())

                if vals:
                    parsed_vals = {parser(v) for v in vals}
                    if len(parsed_vals) > 1:
                        output[pair_id][fact] = "CONFLICT"
                    else:
                        output[pair_id][fact] = [parsed_vals.pop(), doc]
                    continue

                # Try fallback document if primary has no value
                if 'fallback' in source:
                    doc_fb, field_fb, parser_fb = source['fallback']
                    vals_fb = data.get(doc_fb, {}).get(po, {}).get(field_fb, set())
                    if vals_fb:
                        parsed_vals = {parser_fb(v) for v in vals_fb}
                        if len(parsed_vals) > 1:
                            output[pair_id][fact] = "CONFLICT"
                        else:
                            output[pair_id][fact] = [parsed_vals.pop(), doc_fb]
                        continue

                output[pair_id][fact] = "ABSENT"

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
