import sys
import os
import re
import json
from datetime import date, timedelta
from decimal import Decimal

def epd_to_date(epd_str):
    if epd_str == 'NULL': 
        return None
    epd = int(epd_str)
    return (date(1970, 1, 1) + timedelta(days=epd)).strftime('%Y-%m-%d')

def cents_to_usd(cents_str):
    if cents_str == 'NULL': 
        return None
    return str(Decimal(cents_str) / 100)

def parse_units(unit_str):
    if unit_str == 'NULL': 
        return None
    return unit_str

def parse_sql_values(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Match tuples like (1, 'PO-40415', 20515, 11400000, 129)
    # Group 1: ord_code (e.g., PO-40415)
    # Group 2: the rest of the tuple (e.g., , 20515, 11400000, 129)
    tuples = re.findall(r'\(\s*\d+,\s*\'([^\']+)\'([^)]*)\)', content)

    records = []
    for ord_code, rest in tuples:
        parts = [p.strip() for p in rest.split(',') if p.strip()]
        records.append((ord_code, parts))
    return records

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    data = {
        'invoices': {},
        'payments': {},
        'purchase_orders': {},
        'receipts': {},
        'warehouse_scans': {}
    }

    def add_value(file_key, ord_code, field, value):
        if value is None: 
            return
        if ord_code not in data[file_key]:
            data[file_key][ord_code] = {}
        if field not in data[file_key][ord_code]:
            data[file_key][ord_code][field] = set()
        data[file_key][ord_code][field].add(value)

    # Parse invoices.sql
    for ord_code, parts in parse_sql_values(os.path.join(dir_path, 'invoices.sql')):
        if len(parts) >= 3:
            add_value('invoices', ord_code, 'pay_deadline_epd', epd_to_date(parts[0]))
            add_value('invoices', ord_code, 'billed_cents', cents_to_usd(parts[1]))
            add_value('invoices', ord_code, 'billed_unit_ct', parse_units(parts[2]))

    # Parse payments.sql
    for ord_code, parts in parse_sql_values(os.path.join(dir_path, 'payments.sql')):
        if len(parts) >= 1:
            add_value('payments', ord_code, 'funds_out_epd', epd_to_date(parts[0]))

    # Parse purchase_orders.sql
    for ord_code, parts in parse_sql_values(os.path.join(dir_path, 'purchase_orders.sql')):
        if len(parts) >= 1:
            add_value('purchase_orders', ord_code, 'commit_cents', cents_to_usd(parts[0]))

    # Parse receipts.sql
    for ord_code, parts in parse_sql_values(os.path.join(dir_path, 'receipts.sql')):
        if len(parts) >= 2:
            add_value('receipts', ord_code, 'dock_unit_ct', parse_units(parts[0]))
            add_value('receipts', ord_code, 'goods_in_epd', epd_to_date(parts[1]))

    # Parse warehouse_scans.sql
    for ord_code, parts in parse_sql_values(os.path.join(dir_path, 'warehouse_scans.sql')):
        if len(parts) >= 1:
            add_value('warehouse_scans', ord_code, 'scanner_hit_epd', epd_to_date(parts[0]))

    def get_fact(ord_code, primary_file, primary_field, fallback_file=None, fallback_field=None):
        vals = data[primary_file].get(ord_code, {}).get(primary_field, set())
        if len(vals) > 1:
            return "CONFLICT"
        elif len(vals) == 1:
            return [list(vals)[0], primary_file + ".sql"]

        if fallback_file:
            vals = data[fallback_file].get(ord_code, {}).get(fallback_field, set())
            if len(vals) > 1:
                return "CONFLICT"
            elif len(vals) == 1:
                return [list(vals)[0], fallback_file + ".sql"]

        return "ABSENT"

    # Collect all unique order codes across all parsed files
    all_ord_codes = set()
    for file_data in data.values():
        all_ord_codes.update(file_data.keys())

    all_ord_codes = sorted(list(all_ord_codes))
    rules = ["pa.three_way_match", "pa.paid_in_window"]

    output = {}
    for rule in rules:
        for ord_code in all_ord_codes:
            pair = f"{rule}::{ord_code}"
            if rule == "pa.three_way_match":
                output[pair] = {
                    "invoice amount": get_fact(ord_code, "invoices", "billed_cents"),
                    "order amount": get_fact(ord_code, "purchase_orders", "commit_cents"),
                    "quantity received": get_fact(ord_code, "receipts", "dock_unit_ct"),
                    "quantity invoiced": get_fact(ord_code, "invoices", "billed_unit_ct")
                }
            elif rule == "pa.paid_in_window":
                output[pair] = {
                    "goods received": get_fact(ord_code, "receipts", "goods_in_epd", "warehouse_scans", "scanner_hit_epd"),
                    "payment date": get_fact(ord_code, "payments", "funds_out_epd"),
                    "payment due": get_fact(ord_code, "invoices", "pay_deadline_epd")
                }

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
