import re
import json
import datetime

def process_date(val):
    if val == 'NULL': return None
    d = datetime.date(1970, 1, 1) + datetime.timedelta(days=int(val))
    return d.strftime('%Y-%m-%d')

def process_usd(val):
    if val == 'NULL': return None
    return f"{int(val) / 100:.2f}"

def process_unit(val):
    if val == 'NULL': return None
    return val.strip()

FACTS = {
    'pa.three_way_match': {
        'invoice amount': {
            'sources': [{'doc': 'invoices', 'index': 2}],
            'process': process_usd
        },
        'order amount': {
            'sources': [{'doc': 'purchase_orders', 'index': 0}],
            'process': process_usd
        },
        'quantity received': {
            'sources': [{'doc': 'receipts', 'index': 0}],
            'process': process_unit
        },
        'quantity invoiced': {
            'sources': [{'doc': 'invoices', 'index': 1}],
            'process': process_unit
        }
    },
    'pa.paid_in_window': {
        'goods received': {
            'sources': [
                {'doc': 'receipts', 'index': 1},
                {'doc': 'warehouse_scans', 'index': 0}
            ],
            'process': process_date
        },
        'payment date': {
            'sources': [{'doc': 'payments', 'index': 0}],
            'process': process_date
        },
        'payment due': {
            'sources': [{'doc': 'invoices', 'index': 0}],
            'process': process_date
        }
    }
}

def parse_file(filepath):
    data = {}
    if not os.path.exists(filepath):
        return data
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    pattern = r"\(\d+,\s*'([^']+)'\s*,\s*([^)]+)\)"
    for match in re.finditer(pattern, content):
        ord_code = match.group(1)
        vals = [v.strip() for v in match.group(2).split(',')]
        if ord_code not in data:
            data[ord_code] = []
        data[ord_code].append(vals)
    return data

def get_fact(fact_def, ord_code, db):
    for source in fact_def['sources']:
        doc_name = source['doc']
        idx = source['index']

        if doc_name not in db:
            continue

        records = db[doc_name].get(ord_code, [])
        values = set()
        for record in records:
            if idx < len(record):
                val = record[idx]
                if val != 'NULL':
                    processed = fact_def['process'](val)
                    if processed is not None:
                        values.add(processed)

        if len(values) == 1:
            return [list(values)[0], doc_name]
        elif len(values) > 1:
            return "CONFLICT"

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dpath = sys.argv[1]

    db = {}
    docs = ['invoices', 'payments', 'purchase_orders', 'receipts', 'requisitions', 'warehouse_scans']
    for doc in docs:
        filepath = os.path.join(dpath, f"{doc}.sql")
        db[doc] = parse_file(filepath)

    all_ords = set()
    for doc_data in db.values():
        all_ords.update(doc_data.keys())

    rules = ['pa.three_way_match', 'pa.paid_in_window']

    result = {}
    for rule in rules:
        for ord_code in sorted(all_ords):
            pair_id = f"{rule}::{ord_code}"
            fact_results = {}
            for fact_name, fact_def in FACTS[rule].items():
                fact_results[fact_name] = get_fact(fact_def, ord_code, db)
            result[pair_id] = fact_results

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
