import sys
import os
import json

def parse_edi(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = content.split('~')
    loops = []
    current_loop = []
    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        parts = seg.split('*')
        if parts[0] == 'LX':
            if current_loop:
                loops.append(current_loop)
            current_loop = [parts]
        elif current_loop:
            current_loop.append(parts)
    if current_loop:
        loops.append(current_loop)
    return loops

def extract_facts(loops, file_type):
    data = {}
    for loop in loops:
        po_id = None
        loop_facts = {}
        for parts in loop:
            if len(parts) >= 3 and parts[0] == 'REF' and parts[1] == 'PO':
                po_id = parts[2]

            k, v = None, None
            if file_type == 'invoices':
                if len(parts) >= 2 and parts[0] == 'TDS':
                    val = int(parts[1])
                    k, v = 'invoice amount', f"{val/100:.2f}"
                elif len(parts) >= 3 and parts[0] == 'QTY' and parts[1] == 'D1':
                    k, v = 'quantity invoiced', parts[2]
                elif len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '481' and parts[2] == 'D8':
                    date_str = parts[3]
                    k, v = 'payment due', f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

            elif file_type == 'purchase_orders':
                if len(parts) >= 3 and parts[0] == 'AMT' and parts[1] == 'TT':
                    k, v = 'order amount', f"{float(parts[2]):.2f}"

            elif file_type == 'receipts':
                if len(parts) >= 3 and parts[0] == 'QTY' and parts[1] == 'RC':
                    k, v = 'quantity received', parts[2]
                elif len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '050' and parts[2] == 'D8':
                    date_str = parts[3]
                    k, v = 'goods received', f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

            elif file_type == 'payments':
                if len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '234' and parts[2] == 'D8':
                    date_str = parts[3]
                    k, v = 'payment date', f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

            elif file_type == 'warehouse_scans':
                if len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '945' and parts[2] == 'D8':
                    date_str = parts[3]
                    k, v = 'goods received', f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

            if k and v is not None:
                if k not in loop_facts:
                    loop_facts[k] = set()
                loop_facts[k].add(v)

        if po_id:
            if po_id not in data:
                data[po_id] = {}
            for k, vals in loop_facts.items():
                if k not in data[po_id]:
                    data[po_id][k] = set()
                data[po_id][k].update(vals)

    return data

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    file_types = [
        ("invoices", "invoices.edi"),
        ("purchase_orders", "purchase_orders.edi"),
        ("receipts", "receipts.edi"),
        ("payments", "payments.edi"),
        ("warehouse_scans", "warehouse_scans.edi")
    ]

    all_data = {}
    for ftype, fname in file_types:
        filepath = os.path.join(dir_path, fname)
        loops = parse_edi(filepath)
        all_data[ftype] = extract_facts(loops, ftype)

    known_files = {
        "invoices.edi", "payments.edi", "purchase_orders.edi", 
        "receipts.edi", "requisitions.edi", "warehouse_scans.edi"
    }

    all_po_ids = set()
    if os.path.exists(dir_path):
        for filename in os.listdir(dir_path):
            if filename in known_files:
                filepath = os.path.join(dir_path, filename)
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
                    for seg in content.split('~'):
                        parts = seg.strip().split('*')
                        if len(parts) >= 3 and parts[0] == 'REF' and parts[1] == 'PO':
                            all_po_ids.add(parts[2])

    rules_config = {
        "pa.three_way_match": {
            "invoice amount": [("invoices", "invoices.edi")],
            "order amount": [("purchase_orders", "purchase_orders.edi")],
            "quantity received": [("receipts", "receipts.edi")],
            "quantity invoiced": [("invoices", "invoices.edi")]
        },
        "pa.paid_in_window": {
            "goods received": [("receipts", "receipts.edi"), ("warehouse_scans", "warehouse_scans.edi")],
            "payment date": [("payments", "payments.edi")],
            "payment due": [("invoices", "invoices.edi")]
        }
    }

    output = {}
    for rule_name in ["pa.three_way_match", "pa.paid_in_window"]:
        for po_id in sorted(list(all_po_ids)):
            pair_id = f"{rule_name}::{po_id}"
            pair_result = {}

            for fact_name, sources in rules_config[rule_name].items():
                fact_result = "ABSENT"
                for ftype, fname in sources:
                    if po_id in all_data[ftype] and fact_name in all_data[ftype][po_id]:
                        vals = all_data[ftype][po_id][fact_name]
                        if len(vals) > 1:
                            fact_result = "CONFLICT"
                            break
                        elif len(vals) == 1:
                            val = list(vals)[0]
                            fact_result = [val, fname]
                            break
                pair_result[fact_name] = fact_result

            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
