import sys
import os
import json

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    all_data = {
        "invoices": {},
        "purchase_orders": {},
        "receipts": {},
        "warehouse_scans": {},
        "payments": {}
    }
    all_pos = set()

    def add_val(doc, po, fact, val):
        if po not in all_data[doc]:
            all_data[doc][po] = {}
        if fact not in all_data[doc][po]:
            all_data[doc][po][fact] = set()
        all_data[doc][po][fact].add(val)

    def parse_file(filename, doc_name, extract_fn):
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            return
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        current_po = None
        current_loop_data = []

        def commit():
            if current_po:
                all_pos.add(current_po)
                for fact, val in current_loop_data:
                    if doc_name:
                        add_val(doc_name, current_po, fact, val)

        for seg in content.replace('\n', '').split('~'):
            parts = seg.split('*')
            if not parts or parts[0] == '':
                continue

            if parts[0] == 'LX':
                commit()
                current_po = None
                current_loop_data = []
            elif parts[0] == 'SE':
                commit()
                current_po = None
                current_loop_data = []
            elif parts[0] == 'REF' and len(parts) >= 3 and parts[1] == 'PO':
                current_po = parts[2]
            else:
                fact, val = extract_fn(parts)
                if fact and val is not None:
                    current_loop_data.append((fact, val))
        commit()

    def extract_invoices(parts):
        if parts[0] == 'TDS' and len(parts) >= 2:
            v = parts[1]
            if len(v) < 3:
                v = v.zfill(3)
            return 'invoice amount', v[:-2] + '.' + v[-2:]
        elif parts[0] == 'QTY' and len(parts) >= 3 and parts[1] == 'D1':
            return 'quantity invoiced', parts[2]
        elif parts[0] == 'DTP' and len(parts) >= 4 and parts[1] == '481' and parts[2] == 'D8':
            v = parts[3]
            if len(v) == 8:
                return 'payment due', f"{v[:4]}-{v[4:6]}-{v[6:]}"
        return None, None

    def extract_purchase_orders(parts):
        if parts[0] == 'AMT' and len(parts) >= 3 and parts[1] == 'TT':
            return 'order amount', parts[2]
        return None, None

    def extract_receipts(parts):
        if parts[0] == 'QTY' and len(parts) >= 3 and parts[1] == 'RC':
            return 'quantity received', parts[2]
        elif parts[0] == 'DTP' and len(parts) >= 4 and parts[1] == '050' and parts[2] == 'D8':
            v = parts[3]
            if len(v) == 8:
                return 'goods received', f"{v[:4]}-{v[4:6]}-{v[6:]}"
        return None, None

    def extract_warehouse_scans(parts):
        if parts[0] == 'DTP' and len(parts) >= 4 and parts[1] == '945' and parts[2] == 'D8':
            v = parts[3]
            if len(v) == 8:
                return 'goods received', f"{v[:4]}-{v[4:6]}-{v[6:]}"
        return None, None

    def extract_payments(parts):
        if parts[0] == 'DTP' and len(parts) >= 4 and parts[1] == '234' and parts[2] == 'D8':
            v = parts[3]
            if len(v) == 8:
                return 'payment date', f"{v[:4]}-{v[4:6]}-{v[6:]}"
        return None, None

    def extract_requisitions(parts):
        return None, None

    parse_file("invoices.edi", "invoices", extract_invoices)
    parse_file("purchase_orders.edi", "purchase_orders", extract_purchase_orders)
    parse_file("receipts.edi", "receipts", extract_receipts)
    parse_file("warehouse_scans.edi", "warehouse_scans", extract_warehouse_scans)
    parse_file("payments.edi", "payments", extract_payments)
    parse_file("requisitions.edi", None, extract_requisitions)

    def get_fact(po, fact_name, primary_doc, fallback_doc=None):
        def get_from_doc(doc):
            if doc not in all_data:
                return "ABSENT"
            if po not in all_data[doc]:
                return "ABSENT"
            if fact_name not in all_data[doc][po]:
                return "ABSENT"
            vals = all_data[doc][po][fact_name]
            if len(vals) == 0:
                return "ABSENT"
            if len(vals) > 1:
                return "CONFLICT"
            return list(vals)[0]

        val = get_from_doc(primary_doc)
        if val not in ("ABSENT", "CONFLICT"):
            return [val, primary_doc]
        elif val == "CONFLICT":
            return "CONFLICT"
        else:
            if fallback_doc:
                f_val = get_from_doc(fallback_doc)
                if f_val not in ("ABSENT", "CONFLICT"):
                    return [f_val, fallback_doc]
                elif f_val == "CONFLICT":
                    return "CONFLICT"
                else:
                    return "ABSENT"
            else:
                return "ABSENT"

    output = {}
    for po in sorted(all_pos):
        output[f"pa.three_way_match::{po}"] = {
            "invoice amount": get_fact(po, "invoice amount", "invoices"),
            "order amount": get_fact(po, "order amount", "purchase_orders"),
            "quantity received": get_fact(po, "quantity received", "receipts"),
            "quantity invoiced": get_fact(po, "quantity invoiced", "invoices")
        }
        output[f"pa.paid_in_window::{po}"] = {
            "goods received": get_fact(po, "goods received", "receipts", "warehouse_scans"),
            "payment date": get_fact(po, "payment date", "payments"),
            "payment due": get_fact(po, "payment due", "invoices")
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
