import sys
import os
import re
import json
import collections

def parse_date(d_str):
    d_str = d_str.strip().replace('.', '')
    m = re.search(r'([A-Za-z]+)\s+(\d+)(?:st|nd|rd|th)?,?\s+(\d{4})', d_str)
    if m:
        month_str, day_str, year_str = m.groups()
    else:
        m = re.search(r'(\d+)(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})', d_str)
        if m:
            day_str, month_str, year_str = m.groups()
        else:
            return None

    months = {
        'jan': '01', 'january': '01',
        'feb': '02', 'february': '02',
        'mar': '03', 'march': '03',
        'apr': '04', 'april': '04',
        'may': '05',
        'jun': '06', 'june': '06',
        'jul': '07', 'july': '07',
        'aug': '08', 'august': '08',
        'sep': '09', 'september': '09',
        'oct': '10', 'october': '10',
        'nov': '11', 'november': '11',
        'dec': '12', 'december': '12'
    }
    month = months[month_str.lower()]
    day = f"{int(day_str):02d}"
    return f"{year_str}-{month}-{day}"

def extract_invoice_amount(text):
    m = re.search(r"(?:Invoice total is|The vendor's bill comes to) (?:\$([\d,]+)|([\d,]+) dollars)", text)
    if m:
        val = m.group(1) or m.group(2)
        return val.replace(',', '')
    return None

def extract_quantity_invoiced(text):
    if "doesn't show a unit count" in text:
        return "ABSENT"
    m = re.search(r"(?:Bill lists ([\d,]+) (?:units|pieces)|They charged us for ([\d,]+) (?:units|pieces))", text)
    if m:
        val = m.group(1) or m.group(2)
        return val.replace(',', '')
    return None

def extract_payment_due(text):
    if "no payment deadline printed" in text:
        return "ABSENT"
    m = re.search(r"(?:Payment has to go out by|The bill must be settled no later than) ([A-Za-z0-9, ]+?)\.", text)
    if m:
        return parse_date(m.group(1))
    return None

def extract_order_amount(text):
    m = re.search(r"(?:The PO was raised for|Committed value on the PO is) (?:\$([\d,]+)|([\d,]+) dollars)", text)
    if m:
        val = m.group(1) or m.group(2)
        return val.replace(',', '')
    return None

def extract_quantity_received(text):
    m = re.search(r"(?:Receiving tallied ([\d,]+) (?:units|pieces)|We counted ([\d,]+) (?:units|pieces))", text)
    if m:
        val = m.group(1) or m.group(2)
        return val.replace(',', '')
    return None

def extract_goods_received_receipts(text):
    if "don't have a booking-in day" in text:
        return "ABSENT"
    m = re.search(r"(?:It was booked in on|The delivery was logged as received on) ([A-Za-z0-9, ]+?)\.", text)
    if m:
        return parse_date(m.group(1))
    return None

def extract_goods_received_scans(text):
    m = re.search(r"(?:Scanner stamp at the dock reads|The dock scanner picked it up on) ([A-Za-z0-9, ]+?)\.", text)
    if m:
        return parse_date(m.group(1))
    return None

def extract_payment_date(text):
    if "no release-of-funds day" in text:
        return "ABSENT"
    m = re.search(r"(?:We sent the money on|Funds were released to the vendor on) ([A-Za-z0-9, ]+?)\.", text)
    if m:
        return parse_date(m.group(1))
    return None

def process_file(filepath, extractors):
    results = collections.defaultdict(lambda: collections.defaultdict(set))
    if not os.path.exists(filepath):
        return results
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    messages = content.split('========================================================================')
    for msg in messages:
        msg = msg.strip()
        if not msg: continue

        m_subj = re.search(r'Subject: .*?(PO-\d+)', msg)
        if not m_subj: continue
        po = m_subj.group(1)

        for fact_name, func in extractors.items():
            val = func(msg)
            if val is not None:
                results[po][fact_name].add(val)

    return results

def resolve_values(val_set):
    if not val_set:
        return "ABSENT"
    if len(val_set) == 1:
        return list(val_set)[0]
    return "CONFLICT"

def main():
    if len(sys.argv) < 2:
        return
    data_dir = sys.argv[1]

    extractors_map = {
        'invoices.txt': {
            'invoice amount': extract_invoice_amount,
