import sys
import os
import re
import json
import collections

def parse_date(date_str):
    months = {
        'jan': '01', 'january': '01',
        'feb': '02', 'february': '02',
        'mar': '03', 'march': '03',
        'apr': '04', 'april': '04',
        'may': '05',
        'jun': '06', 'june': '06',
        'jul': '07', 'july': '07',
        'aug': '08', 'august': '08',
        'sep': '09', 'september': '09',
        'oct': '10', 'october': '10',
        'nov': '11', 'november': '11',
        'dec': '12', 'december': '12'
    }

    m = re.search(r'([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?,\s+(\d{4})', date_str)
    if m:
        month, day, year = m.groups()
        return f"{year}-{months[month.lower()]}-{int(day):02d}"

    m = re.search(r'(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})', date_str)
    if m:
        day, month, year = m.groups()
        return f"{year}-{months[month.lower()]}-{int(day):02d}"

    return None

ABSENT_STRINGS = {
    "The bill total isn't on the copy I have.",
    "There's no payment deadline printed on the bill.",
    "No count was taken on arrival.",
    "I don't have a booking-in day."
}

def extract_field(msg, regexes, is_date=False, is_amount=False):
    for r in regexes:
        m = re.search(r, msg)
        if m:
            val = m.group(1)
            if val in ABSENT_STRINGS:
                return "ABSENT"
            if is_date:
                return parse_date(val)
            if is_amount:
                return val.replace(',', '')
            return val
    return None

def parse_messages(file_content):
    messages = re.split(r'^={10,}$', file_content, flags=re.MULTILINE)
    parsed = []
    for msg in messages:
        msg = msg.strip()
        if not msg: continue
        subj_m = re.search(r'^Subject:.*?(PO-\d+)', msg, re.MULTILINE)
        if not subj_m: continue
        po = subj_m.group(1)
        parsed.append((po, msg))
    return parsed

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    data = collections.defaultdict(lambda: collections.defaultdict(lambda: collections.defaultdict(set)))
    all_pos = set()

    # Regexes for extraction
    invoice_amount_re = [
        r"Invoice total is \$?([\d,]+)(?: dollars)? all told\.",
        r"The vendor's bill comes to \$?([\d,]+)(?: dollars)? in total\.",
        r"(The bill total isn't on the copy I have\.)"
    ]
    payment_due_re = [
        r"Payment has to go out by (.*?)\.",
        r"The bill must be settled no later than (.*?)\.",
        r"(There's no payment deadline printed on the bill\.)"
    ]
    quantity_invoiced_re = [
        r"They charged us for (\d+) (?:units|pieces) on that bill\.",
        r"Bill lists (\d+) (?:units|pieces) as the chargeable count\."
    ]
    order_amount_re = [
        r"The PO was raised for \$?([\d,]+)(?: dollars)? in total\.",
        r"Committed value on the PO is \$?([\d,]+)(?: dollars)? overall\."
    ]
    quantity_received_re = [
        r"Receiving tallied (\d+) (?:pieces|units) off the truck\.",
        r"We counted (\d+) (?:pieces|units) on arrival\.",
        r"(No count was taken on arrival\.)"
    ]
    goods_received_re = [
        r"It was booked in on (.*?)\.",
        r"The delivery was logged as received on (.*?)\.",
        r"(I don't have a booking-in day\.)"
    ]
    warehouse_scan_re = [
        r"Scanner stamp at the dock reads (.*?)\.",
        r"The dock scanner picked it up on (.*?)\."
    ]
    payment_date_re = [
        r"Funds were released to the vendor on (.*?)\.",
        r"We sent the money on (.*?)\."
    ]

    # Read files and extract facts
    files = {
        'invoices': 'invoices.txt',
        'purchase_orders': 'purchase_orders.txt',
        'receipts': 'receipts.txt',
        'warehouse_scans': 'warehouse_scans.txt',
        'payments': 'payments.txt'
    }

    for doc, filename in files.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                all_pos.update(re.findall(r'PO-\d+', content))

                for po, msg in parse_messages(content):
                    if doc == 'invoices':
                        amt = extract_field(msg, invoice_amount_re, is_amount=True)
                        if amt: data[po][doc]['invoice amount'].add(amt)

                        due = extract_field(msg, payment_due_re, is_date=True)
                        if due: data[po][doc]['payment due'].add(due)

                        qty = extract_field(msg, quantity_invoiced_re)
                        if qty: data[po][doc]['quantity invoiced'].add(qty)

                    elif doc == 'purchase_orders':
                        amt = extract_field(msg, order_amount_re, is_amount=True)
                        if amt: data[po][doc]['order amount'].add(amt)

                    elif doc == 'receipts':
                        qty = extract_field(msg, quantity_received_re)
                        if qty: data[po][doc]['quantity received'].add(qty)

                        recv = extract_field(msg, goods_received_re, is_date=True)
                        if recv: data[po][doc]['goods received'].add(recv)

                    elif doc == 'warehouse_scans':
                        recv = extract_field(msg, warehouse_scan_re, is_date=True)
                        if recv: data[po][doc]['goods received'].add(recv)

                    elif doc == 'payments':
                        pdate = extract_field(msg, payment_date_re, is_date=True)
                        if pdate: data[po][doc]['payment date'].add(pdate)

    # Check requisitions.txt just to ensure we don't miss any PO numbers
    req_path = os.path.join(dir_path, 'requisitions.txt')
    if os.path.exists(req_path):
        with open(req_path, 'r', encoding='utf-8') as f:
            all_pos.update(re.findall(r'PO-\d+', f.read()))

    def resolve_field(po, doc, field, fallback_doc=None):
        vals = data[po][doc][field]
        if len(vals) > 1:
            return "CONFLICT"
        elif len(vals) == 1:
            val = list(vals)[0]
            if val != "ABSENT":
                return [val, doc]

        if fallback_doc:
            fb_vals = data[po][fallback_doc][field]
            if len(fb_vals) > 1:
                return "CONFLICT"
            elif len(fb_vals) == 1:
                val = list(fb_vals)[0]
                if val != "ABSENT":
                    return [val, fallback_doc]

        return "ABSENT"

    results = {}
    for po in sorted(list(all_pos)):
        # pa.three_way_match
        pair_id = f"pa.three_way_match::{po}"
        results[pair_id] = {
            "invoice amount": resolve_field(po, "invoices", "invoice amount"),
            "order amount": resolve_field(po, "purchase_orders", "order amount"),
            "quantity received": resolve_field(po, "receipts", "quantity received"),
            "quantity invoiced": resolve_field(po, "invoices", "quantity invoiced")
        }

        # pa.paid_in_window
        pair_id = f"pa.paid_in_window::{po}"
        results[pair_id] = {
            "goods received": resolve_field(po, "receipts", "goods received", "warehouse_scans"),
            "payment date": resolve_field(po, "payments", "payment date"),
            "payment due": resolve_field(po, "invoices", "payment due")
        }

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()
