import sys
import os
import csv
import json
import datetime

def parse_crosstab(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='\t')
        rows = [row for row in reader if row and not row[0].startswith('#')]

    order_keys = []
    for row in rows:
        if row[0] == 'order.key':
            order_keys = row[1:]
            break

    data = {}
    for row in rows:
        attr = row[0]
        if attr in ('attribute', 'order.key'):
            continue
        if attr not in data:
            data[attr] = {}
        for i, val in enumerate(row[1:]):
            if i < len(order_keys):
                entity = order_keys[i]
                if val != '~':
                    if entity not in data[attr]:
                        data[attr][entity] = set()
                    data[attr][entity].add(val)
    return data, order_keys

def format_value(val, attr):
    if attr.endswith('.wk'):
        dt = datetime.datetime.strptime(val, "%G-W%V-%u")
        return dt.strftime("%Y-%m-%d")
    return val

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    files = [
        "invoices.tsv",
        "payments.tsv",
        "purchase_orders.tsv",
        "receipts.tsv",
        "requisitions.tsv",
        "warehouse_scans.tsv"
    ]

    db = {}
    all_entities = set()

    for fname in files:
        fpath = os.path.join(dir_path, fname)
        if os.path.exists(fpath):
            data, keys = parse_crosstab(fpath)
            db[fname] = data
            all_entities.update(keys)

    rules = {
        "pa.three_way_match": {
            "invoice amount": [("invoices.tsv", "bill.value.usd")],
            "order amount": [("purchase_orders.tsv", "order.commit.usd")],
            "quantity received": [("receipts.tsv", "goodsin.units")],
            "quantity invoiced": [("invoices.tsv", "bill.qty.units")]
        },
        "pa.paid_in_window": {
            "goods received": [("receipts.tsv", "goodsin.day.wk"), ("warehouse_scans.tsv", "scanner.hit.wk")],
            "payment date": [("payments.tsv", "funds.out.wk")],
            "payment due": [("invoices.tsv", "bill.deadline.wk")]
        }
    }

    sorted_entities = sorted(list(all_entities))
    output = {}

    for rule_name in ["pa.three_way_match", "pa.paid_in_window"]:
        for entity in sorted_entities:
            pair_id = f"{rule_name}::{entity}"

            rule_facts = rules[rule_name]
            pair_result = {}

            for fact_name, sources in rule_facts.items():
                fact_val = "ABSENT"

                for doc, attr in sources:
                    if doc in db and attr in db[doc]:
                        if entity in db[doc][attr]:
                            vals = db[doc][attr][entity]
                            if len(vals) == 1:
                                raw_val = list(vals)[0]
                                formatted_val = format_value(raw_val, attr)
                                fact_val = [formatted_val, doc]
                                break
                            elif len(vals) > 1:
                                fact_val = "CONFLICT"
                                break

                pair_result[fact_name] = fact_val

            output[pair_id] = pair_result

