import sys
import os
import json
import datetime

def iso_week_to_date(iso_week_str):
    if iso_week_str == '~':
        return '~'
    dt = datetime.datetime.strptime(iso_week_str, "%G-W%V-%u")
    return dt.strftime("%Y-%m-%d")

def read_tsv(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    data_lines = [line.strip('\n').split('\t') for line in lines if not line.startswith('#') and line.strip()]
    if not data_lines:
        return {}

    attributes = [row[0] for row in data_lines]

    try:
        key_idx = attributes.index('order.key')
    except ValueError:
        return {}

    records_by_key = {}
    num_cols = len(data_lines[key_idx])
    for col_idx in range(1, num_cols):
        key = data_lines[key_idx][col_idx]
        if key == '~':
            continue
        if key not in records_by_key:
            records_by_key[key] = {attr: [] for attr in attributes}

        for row_idx, attr in enumerate(attributes):
            if col_idx < len(data_lines[row_idx]):
                val = data_lines[row_idx][col_idx]
                if val != '~':
                    records_by_key[key][attr].append(val)

    return records_by_key

def get_fact(records_by_key, key, attr, is_date=False):
    if key not in records_by_key:
        return "ABSENT"
    vals = records_by_key[key].get(attr, [])
    if not vals:
        return "ABSENT"
    unique_vals = set(vals)
    if len(unique_vals) > 1:
        return "CONFLICT"
    val = unique_vals.pop()
    if is_date:
        return iso_week_to_date(val)
    return val

def resolve_fact(docs_data, key, sources):
    for doc_name, file_name, attr, is_date in sources:
        doc_data = docs_data.get(file_name, {})
        res = get_fact(doc_data, key, attr, is_date)
        if res != "ABSENT":
            if res == "CONFLICT":
                return "CONFLICT"
            else:
                return [res, doc_name]
    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    files_to_read = [
        "invoices.tsv",
        "payments.tsv",
        "purchase_orders.tsv",
        "receipts.tsv",
        "requisitions.tsv",
        "warehouse_scans.tsv"
    ]

    docs_data = {}
    all_keys = set()

    for fname in files_to_read:
        fpath = os.path.join(dir_path, fname)
        if os.path.exists(fpath):
            data = read_tsv(fpath)
            docs_data[fname] = data
            all_keys.update(data.keys())

    all_keys = sorted(list(all_keys))

    rules = {
        "pa.three_way_match": {
            "invoice amount": [("invoices", "invoices.tsv", "bill.value.usd", False)],
            "order amount": [("purchase_orders", "purchase_orders.tsv", "order.commit.usd", False)],
            "quantity received": [("receipts", "receipts.tsv", "goodsin.units", False)],
            "quantity invoiced": [("invoices", "invoices.tsv", "bill.qty.units", False)]
        },
        "pa.paid_in_window": {
            "goods received": [
                ("receipts", "receipts.tsv", "goodsin.day.wk", True),
                ("warehouse_scans", "warehouse_scans.tsv", "scanner.hit.wk", True)
            ],
            "payment date": [("payments", "payments.tsv", "funds.out.wk", True)],
            "payment due": [("invoices", "invoices.tsv", "bill.deadline.wk", True)]
        }
    }

    output = {}

    for rule_name, facts in rules.items():
        for key in all_keys:
            pair_id = f"{rule_name}::{key}"
            pair_result = {}
            for fact_name, sources in facts.items():
                pair_result[fact_name] = resolve_fact(docs_data, key, sources)
            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
```

