    data = {}
    if not os.path.exists(filepath):
        return data
    with open(filepath, 'r', encoding='utf-8') as f:
        header_skipped = False
        for line in f:
            if line.startswith('#'):
                continue
            if not header_skipped:
                header_skipped = True
                continue
            parts = line.strip('\n').split('|')
            if len(parts) <= max(key_idx, val_idx):
                continue
            key = parts[key_idx]
            val = parts[val_idx]
            if not val:
                continue
            val = transform(val)
            if key not in data:
                data[key] = set()
            data[key].add(val)
    return data

def resolve_fact(entity, primary_data, primary_doc, fallback_data=None, fallback_doc=None):
