import sys
import os
import json
import re

def parse_date(s):
    m = re.search(r'([A-Z][a-z]+)\.?\s+(\d{1,2}),\s+(\d{4})', s)
    if not m: return None
    month_str, day_str, year_str = m.groups()
    month_prefix = month_str[:3].lower()
    months = {
        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12'
    }
    month = months.get(month_prefix, '01')
    day = f"{int(day_str):02d}"
    return f"{year_str}-{month}-{day}"

def parse_amount(s):
    m = re.search(r'USD\s+([\d,]+\.\d{2})', s)
    if m:
        return m.group(1).replace(',', '')
    return None

def parse_units(s):
    m = re.search(r'([\d,]+)\s+pcs', s)
    if m:
        return m.group(1).replace(',', '')
    return None

def extract_records(html_content):
    records = []
    sheets = html_content.split('<article class="sheet"')[1:]
    for sheet in sheets:
        record = {}
        fields = re.findall(r'<th>(.*?)</th>\s*<td[^>]*>(.*?)</td>', sheet, re.DOTALL)
        for k, v in fields:
            k = k.strip()
            v = re.sub(r'<[^>]+>', '', v).strip()
            record[k] = v

        if 'Procurement reference' in record:
            m_po = re.search(r'(PO-\d+)', record['Procurement reference'])
            if m_po:
                record['PO'] = m_po.group(1)
            else:
                continue
        else:
            continue

        records.append(record)
    return records

def get_fact_value(doc_name, po, field_name, parser, records_by_doc):
    if doc_name not in records_by_doc:
        return "ABSENT"

    values = set()
    for record in records_by_doc[doc_name]:
        if record.get('PO') == po:
            raw_val = record.get(field_name)
            if raw_val is not None:
                val = parser(raw_val)
                if val is not None:
                    values.add(val)

    if len(values) == 0:
        return "ABSENT"
    elif len(values) == 1:
        return list(values)[0]
    else:
        return "CONFLICT"

def resolve_fact(po, fact_def, records_by_doc):
    doc = fact_def["doc"]
    field = fact_def["field"]
    parser = fact_def["parser"]

    val = get_fact_value(doc, po, field, parser, records_by_doc)

    if val == "ABSENT" and "fallback_doc" in fact_def:
        fb_doc = fact_def["fallback_doc"]
        fb_field = fact_def["fallback_field"]
        fb_val = get_fact_value(fb_doc, po, fb_field, parser, records_by_doc)
        if fb_val in ["ABSENT", "CONFLICT"]:
            return fb_val
        else:
            return [fb_val, fb_doc]

    if val in ["ABSENT", "CONFLICT"]:
        return val
    else:
        return [val, doc]

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    records_by_doc = {}
    for filename in os.listdir(dir_path):
        if filename.endswith('.html'):
            doc_name = filename[:-5]
            filepath = os.path.join(dir_path, filename)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
            records_by_doc[doc_name] = extract_records(content)

    all_pos = set()
    for doc_records in records_by_doc.values():
        for r in doc_records:
            if 'PO' in r:
                all_pos.add(r['PO'])

    rules = {
        "pa.three_way_match": {
            "invoice amount": {"doc": "invoices", "field": "Invoice grand total", "parser": parse_amount},
            "order amount": {"doc": "purchase_orders", "field": "Total order value", "parser": parse_amount},
            "quantity received": {"doc": "receipts", "field": "Units counted on delivery", "parser": parse_units},
            "quantity invoiced": {"doc": "invoices", "field": "Units charged", "parser": parse_units}
        },
        "pa.paid_in_window": {
            "goods received": {"doc": "receipts", "field": "Delivery booked", "parser": parse_date, "fallback_doc": "warehouse_scans", "fallback_field": "Dock scanner stamp"},
            "payment date": {"doc": "payments", "field": "Funds released", "parser": parse_date},
            "payment due": {"doc": "invoices", "field": "Payment deadline", "parser": parse_date}
        }
    }

    results = {}
    for rule_name in ["pa.three_way_match", "pa.paid_in_window"]:
        for po in sorted(list(all_pos)):
            pair_id = f"{rule_name}::{po}"
            results[pair_id] = {}
            for fact_name, fact_def in rules[rule_name].items():
                results[pair_id][fact_name] = resolve_fact(po, fact_def, records_by_doc)

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()
