import os
import sys
import re
import json
import html

def parse_date(s):
    m = re.search(r'([A-Z][a-z]+(?:\.)?)\s+(\d+),\s+(\d{4})', s)
    if not m: return None
    month_str, day_str, year_str = m.groups()
    months = {
        'Jan.': '01', 'Feb.': '02', 'March': '03', 'April': '04',
        'May': '05', 'June': '06', 'July': '07', 'Aug.': '08',
        'Sept.': '09', 'Oct.': '10', 'Nov.': '11', 'Dec.': '12'
    }
    return f"{year_str}-{months[month_str]}-{int(day_str):02d}"

def parse_amount(s):
    m = re.search(r'USD\s+([\d,]+\.\d{2})', s)
    if not m: return None
    return m.group(1).replace(',', '')

def parse_units(s):
    m = re.search(r'(\d+)\s+pcs', s)
    if not m: return None
    return m.group(1)

def parse_html(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    sheets = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)
    data = {}

    for sheet in sheets:
        po_match = re.search(r'<th>Procurement reference</th>\s*<td.*?>\s*<strong>\s*(PO-\d+)\s*</strong>\s*</td>', sheet)
        if not po_match:
            continue
        po = po_match.group(1)

        if po not in data:
            data[po] = {}

        fields = re.findall(r'<tr>\s*<th>(.*?)</th>\s*<td.*?>(.*?)</td>\s*</tr>', sheet, re.DOTALL)
        for field_name, field_val in fields:
            field_name = field_name.strip()
            if 'class="void"' in field_val or '&mdash; left blank' in field_val:
                continue

            field_val = re.sub(r'<[^>]+>', '', field_val)
            field_val = html.unescape(field_val).strip()

            if field_name not in data[po]:
                data[po][field_name] = set()
            data[po][field_name].add(field_val)

    return data

def get_fact_value(po, doc_name, field_name, parser, parsed_docs):
    if doc_name not in parsed_docs:
        return "ABSENT"
    doc_data = parsed_docs[doc_name]
    if po not in doc_data:
        return "ABSENT"
    if field_name not in doc_data[po]:
        return "ABSENT"

    values = doc_data[po][field_name]
    parsed_values = set()
    for v in values:
        pv = parser(v)
        if pv is not None:
            parsed_values.add(pv)

    if len(parsed_values) == 0:
        return "ABSENT"
    elif len(parsed_values) > 1:
        return "CONFLICT"
    else:
        return [list(parsed_values)[0], doc_name]

def resolve_fact(po, fact_sources, parsed_docs):
    for doc_name, field_name, parser in fact_sources:
        val = get_fact_value(po, doc_name, field_name, parser, parsed_docs)
        if val == "CONFLICT":
            return "CONFLICT"
        elif val != "ABSENT":
            return val
    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    files_to_parse = [
        'invoices.html',
        'payments.html',
        'purchase_orders.html',
        'receipts.html',
        'requisitions.html',
        'warehouse_scans.html'
    ]

    parsed_docs = {}
    all_pos = set()

    for fname in files_to_parse:
        fpath = os.path.join(dir_path, fname)
        if os.path.exists(fpath):
            doc_name = fname.replace('.html', '')
            parsed_docs[doc_name] = parse_html(fpath)
            all_pos.update(parsed_docs[doc_name].keys())

    all_pos = sorted(list(all_pos))

    RULES = {
        'pa.three_way_match': {
            'invoice amount': [('invoices', 'Invoice grand total', parse_amount)],
            'order amount': [('purchase_orders', 'Total order value', parse_amount)],
            'quantity received': [('receipts', 'Units counted on delivery', parse_units)],
            'quantity invoiced': [('invoices', 'Units charged', parse_units)]
        },
        'pa.paid_in_window': {
            'goods received': [
                ('receipts', 'Delivery booked', parse_date),
                ('warehouse_scans', 'Dock scanner stamp', parse_date)
            ],
            'payment date': [('payments', 'Funds released', parse_date)],
            'payment due': [('invoices', 'Payment deadline', parse_date)]
        }
    }

    output = {}
    for rule_name, rule_facts in RULES.items():
        for po in all_pos:
            pair_id = f"{rule_name}::{po}"
            output[pair_id] = {}
            for fact_name, fact_sources in rule_facts.items():
                output[pair_id][fact_name] = resolve_fact(po, fact_sources, parsed_docs)

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
