    # Find all INSERT INTO statements
    inserts = re.finditer(r'INSERT INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);', content, re.DOTALL)
    for match in inserts:
        cols_str = match.group(1)
        values_str = match.group(2)
        cols = [c.strip() for c in cols_str.split(',')]

        # Extract tuples safely, handling quotes and parentheses
        tuples = []
        in_quotes = False
        in_tuple = False
        current_tup = []

        for char in values_str:
            if char == "'":
                in_quotes = not in_quotes
                current_tup.append(char)
            elif char == '(' and not in_quotes:
                if not in_tuple:
                    in_tuple = True
                else:
                    current_tup.append(char)
            elif char == ')' and not in_quotes:
                if in_tuple:
                    in_tuple = False
                    tuples.append(''.join(current_tup))
                    current_tup = []
                else:
                    current_tup.append(char)
            else:
                if in_tuple:
                    current_tup.append(char)

        # Parse values within each tuple
        for tup in tuples:
            vals = []
            in_quotes = False
            current_val = []
            for char in tup:
                if char == "'":
                    in_quotes = not in_quotes
                elif char == ',' and not in_quotes:
                    vals.append(''.join(current_val).strip())
                    current_val = []
                    continue
                current_val.append(char)
            vals.append(''.join(current_val).strip())

            # Remove surrounding single quotes
            vals = [v[1:-1] if v.startswith("'") and v.endswith("'") else v for v in vals]
            record = dict(zip(cols, vals))
            records.append(record)

    return records

def get_field_values(records, ord_code, field):
    vals = set()
    for r in records:
        if r.get('ord_code') == ord_code:
            val = r.get(field)
            if val is not None and val.upper() != 'NULL':
                vals.add(val)
    return vals

def format_usd(val):
    return str(Decimal(val) / 100)

def format_units(val):
    return str(Decimal(val))

def format_date(val):
    return (date(1970, 1, 1) + timedelta(days=int(val))).isoformat()

def resolve_fact(ord_code, primary_file, primary_field, fallback_file, fallback_field, formatter, data):
    primary_records = data.get(primary_file, [])
    vals = get_field_values(primary_records, ord_code, primary_field)

    if len(vals) > 1:
        return "CONFLICT"
    elif len(vals) == 1:
        val = vals.pop()
        return [formatter(val), primary_file]

    if fallback_file:
        fallback_records = data.get(fallback_file, [])
        vals = get_field_values(fallback_records, ord_code, fallback_field)
        if len(vals) > 1:
            return "CONFLICT"
        elif len(vals) == 1:
            val = vals.pop()
            return [formatter(val), fallback_file]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    data_dir = sys.argv[1]

    files = {
        "invoices": "invoices.sql",
        "payments": "payments.sql",
        "purchase_orders": "purchase_orders.sql",
        "receipts": "receipts.sql",
        "requisitions": "requisitions.sql",
        "warehouse_scans": "warehouse_scans.sql"
    }

    data = {}
    for doc_name, filename in files.items():
        filepath = os.path.join(data_dir, filename)
        data[doc_name] = parse_sql_values(filepath)

    # Discover all unique order codes across all documents
    all_ord_codes = set()
    for records in data.values():
        for r in records:
            if 'ord_code' in r:
                all_ord_codes.add(r['ord_code'])

    rules = ["pa.three_way_match", "pa.paid_in_window"]
    pairs = []
    for rule in rules:
        for ord_code in sorted(all_ord_codes):
            pairs.append(f"{rule}::{ord_code}")

    results = {}
    for pair in pairs:
        rule, ord_code = pair.split("::")
        facts = {}

        if rule == "pa.three_way_match":
            facts["invoice amount"] = resolve_fact(ord_code, "invoices", "billed_cents", None, None, format_usd, data)
            facts["order amount"] = resolve_fact(ord_code, "purchase_orders", "commit_cents", None, None, format_usd, data)
            facts["quantity received"] = resolve_fact(ord_code, "receipts", "dock_unit_ct", None, None, format_units, data)
            facts["quantity invoiced"] = resolve_fact(ord_code, "invoices", "billed_unit_ct", None, None, format_units, data)

        elif rule == "pa.paid_in_window":
            facts["goods received"] = resolve_fact(ord_code, "receipts", "goods_in_epd", "warehouse_scans", "scanner_hit_epd", format_date, data)
            facts["payment date"] = resolve_fact(ord_code, "payments", "funds_out_epd", None, None, format_date, data)
            facts["payment due"] = resolve_fact(ord_code, "invoices", "pay_deadline_epd", None, None, format_date, data)

        results[pair] = facts

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
